const axios = require('axios')
const cheerio = require('cheerio')
const { parseFileSize, getFileSize } = require("../../utils/filesize")
const { author } = require("../../config")


async function mediafire(url) {
    if (!url) throw new Error('URL requerida')

    const { data } = await axios.get(url, {
        headers: {
            'User-Agent': 'Mozilla/5.0'
        }
    })

    const $ = cheerio.load(data)

    const Url = ($('#downloadButton').attr('href') || '').trim()
    const url2 = ($('#download_link > a.retry').attr('href') || '').trim()

    const $intro = $('div.dl-info > div.intro')

    const filename = $intro.find('div.filename').text().trim()
    const filetype = $intro.find('div.filetype > span').eq(0).text().trim()

    const extMatch = /\(\.(.*?)\)/.exec(
        $intro.find('div.filetype > span').eq(1).text()
    )

    const ext = extMatch?.[1]?.trim() || 'bin'

    const $li = $('div.dl-info > ul.details > li')

    const aploud = $li.eq(1).find('span').text().trim()
    const size = $li.eq(0).find('span').text().trim()
    const sizeB = parseFileSize(size)

    if (!Url && !url2) throw new Error('No se pudo obtener el link de descarga')

    return {
        author,
        filename,
        url: Url || url2,
        url2,
        type: filetype,
        ext,
        aploud,
        size,
        sizeB
    }
}

module.exports = { mediafire }